use vstd::prelude::*;

verus! {

/// In‐place reversal of a Vec<u64>.
/// 
/// Post‐condition: the content view `v@` is the reverse of
/// the original content `old(v@)`.
fn reverse(v: &mut Vec<u64>)
    ensures
        // same length
        v.len() == old(v@).len() as usize,
        // ∀ i < old_len.  v@[i] = old(v@)[old_len-1-i]
        forall |i: nat|
            i < old(v@).len() ==>
            v@.index(i) == old(v@).index(old(v@).len() - 1 - i),
{
    let n = v.len();                     // the length as usize
    ghost let old_v: Seq<u64> = v@;     // capture the pre‐state sequence
    let half = n / 2;                    // we only need to swap up to half
    let mut i: usize = 0;

    // We maintain three facts:
    // 1) The first i elements have been reversed: for j < i, v@[j] = old_v[n-1-j].
    // 2) The last  i elements have been reversed: for j < i, v@[n-1-j] = old_v[j].
    // 3) The middle elements [i .. n−i) are still in their original positions.
    while i < half
        invariant
            v.len() == n,
        invariant
            forall |j: nat|
                j < i as nat ==>
                    v@.index(j) == old_v.index(n as nat - 1 - j),
        invariant
            forall |j: nat|
                j < i as nat ==>
                    v@.index(n as nat - 1 - j) == old_v.index(j),
        invariant
            forall |j: nat|
                i as nat <= j && j < n as nat - i as nat ==>
                    v@.index(j) == old_v.index(j),
        decreases half - i,
    {
        // swap positions i and (n-1-i)
        let j = n - 1 - i;
        v.swap(i, j);
        i = i + 1;
    }
}

} // end of verus! block

